#include "TapPanel.hpp"
#include <cassert>
#include <iostream>
int main(){auto p=tap::parsePanelInfo("Scopes host: connected\nhttp://localhost:8765/scopes.html\nhttp://192.168.0.123:8765/scopes.html\nViewers: 2\niPad Pro: listening (resolve)\nDesktop: connected, stopped\nSnapshot: 2026-10-23T17:00:00Z\nPress Refresh status to update.\n");assert(p.host=="connected");assert(p.urls.size()==2);assert(p.viewers.size()==2);assert(p.snapshot=="2026-10-23T17:00:00Z");for(const auto&url:p.urls)assert(url.rfind("http",0)==0);auto offline=tap::parsePanelInfo("Scopes host: unavailable\nLocal address: http://localhost:8765/scopes.html\n");assert(offline.host=="unavailable");assert(offline.urls.size()==1);std::string many="Scopes host: connected\n";for(int i=0;i<50;i++)many+="http://192.168.0."+std::to_string(i)+":8765/scopes.html\n";assert(tap::parsePanelInfo(many).urls.size()==50);std::cout<<"PASS separate host state, all URLs, all viewer states, timestamp, offline address, 50-address list\n";}
